using PipelineForge.Core.Generation;
using PipelineForge.Core.Importing;
using PipelineForge.Core.Model;
using PipelineForge.Core.Presets;

namespace PipelineForge.Tests.Generation;

/// <summary>Every step of project_workflow.docx must be generated by the built-in Secure Java preset.</summary>
public class WorkflowCoverageTests
{
    public static PipelineConfig SecureJava(AgentType agent = AgentType.Kubernetes)
    {
        var config = PresetMerger.Apply(Samples.MavenHelm(), BuiltInPresets.SecureJava.ConfigJson);
        config.Agent.Type = agent;
        return config;
    }

    private static Dictionary<string, string> Files(PipelineConfig config)
    {
        var result = PipelineGenerator.Generate(config);
        Assert.True(result.Success, string.Join("\n", result.Errors));
        return result.Files.ToDictionary(f => f.Path, f => f.Content);
    }

    [Theory]
    [InlineData(AgentType.Kubernetes)]
    [InlineData(AgentType.Docker)]
    public void Built_in_preset_covers_every_workflow_step(AgentType agent)
    {
        var f = Files(SecureJava(agent));
        var jf = f["Jenkinsfile"];
        var security = f["jenkins/stages/security.groovy"];
        var deploy = f["jenkins/stages/deploy.groovy"];
        var dast = f["jenkins/stages/dast.groovy"];

        // 1 Build: Maven Enforcer fails on unpinned versions; builds resolve through Nexus.
        Assert.Contains("maven-enforcer-plugin:3.5.0:enforce", security);
        Assert.Contains("security/maven-enforcer.xml", f.Keys);
        Assert.Contains("<mirrorOf>*</mirrorOf>", f["jenkins/config/maven-settings.xml"]);
        Assert.Contains("-s \"$WORKSPACE/jenkins/config/maven-settings.xml\"", f["jenkins/stages/build.groovy"]);
        // 2 Test
        Assert.Contains("verify", f["jenkins/stages/build.groovy"]);
        // 3 SonarQube with a blocking gate
        Assert.Contains("sonar-maven-plugin", f["jenkins/stages/quality.groovy"]);
        Assert.Contains("waitForQualityGate abortPipeline: true", f["jenkins/stages/quality.groovy"]);
        // 4 Snyk SCA through Nexus
        Assert.Contains("snyk test --all-projects", security);
        // 5 Gitleaks on the diff
        Assert.Contains("--log-opts=$PF_DIFF_BASE..HEAD", security);
        // 6 Snyk IaC only when infrastructure changed
        Assert.Contains("snyk iac test", security);
        Assert.Contains("common.changed(", security);
        // 1-6 run on pull requests
        Assert.Contains("changeRequest()", jf[jf.IndexOf("stage('Secret scan')", StringComparison.Ordinal)..]);
        // 7-8 Package and containerize on merge
        Assert.Contains("stage('Build image')", jf);
        Assert.Contains(agent == AgentType.Kubernetes ? "/kaniko/executor" : "docker build", deploy);
        // 9 Sign, 12 verify, 13 deploy by digest
        Assert.Contains("cosign sign --yes", deploy);
        Assert.Contains("cosign verify --key security/cosign.pub", deploy);
        Assert.Contains("verifyImages(common)", deploy);
        Assert.Contains("images.api.digest=\"$IMAGE_DIGEST_API\"", deploy);
        Assert.Contains("stage('Sign image')", jf);
        // 10 Ephemeral ZAP baseline
        Assert.Contains("stage('Ephemeral DAST')", jf);
        Assert.Contains(agent == AgentType.Kubernetes ? "podTemplate(" : "docker network create --internal", dast);
        Assert.Contains("zap-ephemeral.json", dast);
        // 11 Snyk container scan
        Assert.Contains("snyk container test \"docker-archive:", deploy);
        // 14 Login rate-limit check
        Assert.Contains("stage('Rate-limit check Test')", jf);
        Assert.Contains("jenkins/scripts/rate_limit_check.py", f.Keys);
        // 15 Authenticated two-role scan
        Assert.Contains("zap-admin", f["security/zap/auth-plan.yaml"]);
        Assert.Contains("jenkins/scripts/access_control_check.py", f.Keys);
        Assert.Contains("authenticatedScan", f["Jenkinsfile.scheduled"]);
        // 16 Scheduled baseline every 6 hours
        Assert.Contains("'H */6 * * *'", f["Jenkinsfile.scheduled"]);
        Assert.Contains("dast.baseline(", f["Jenkinsfile.scheduled"]);
        // 17-18 Snyk monitor on deploy
        Assert.Contains("snyk monitor --all-projects", deploy);
        Assert.Contains("snyk container monitor", deploy);
        // 19-21 Jira tickets, deduplicated
        Assert.Contains("jiraNewIssue", f["jenkins/stages/tickets.groovy"]);
        Assert.Contains("labels = pf-${fp}", f["jenkins/stages/tickets.groovy"]);
        Assert.Contains("tickets.file(common, 'ci')", jf);
        Assert.Contains("jira-steps", f["docs/PIPELINE.md"]);
    }

    [Fact]
    public void Generated_groovy_stays_balanced_with_every_feature_on()
    {
        foreach (var agent in new[] { AgentType.Kubernetes, AgentType.Docker })
            foreach (var (path, content) in Files(SecureJava(agent)).Where(kv => kv.Key.StartsWith("Jenkinsfile") || kv.Key.EndsWith(".groovy")))
            {
                Assert.True(PipelineForge.Core.Validation.ConfigValidator.BracesBalanced(content), $"{agent} {path}");
                Assert.DoesNotMatch(@"(?<![A-Za-z])sh\s*""", content);
            }
    }

    [Fact]
    public void Defaults_keep_the_previous_behaviour()
    {
        var f = Files(Samples.MavenHelm());
        Assert.DoesNotContain("Jenkinsfile.scheduled", f.Keys);
        Assert.DoesNotContain("cosign", f["jenkins/stages/deploy.groovy"]);
        Assert.DoesNotContain("changeRequest()", f["Jenkinsfile"][..f["Jenkinsfile"].IndexOf("stage('AI security review')", StringComparison.Ordinal)]);
    }

    [Theory]
    [InlineData("rm -rf /")]
    [InlineData("H */6 * * * ; evil")]
    [InlineData("* *")]
    public void Bad_cron_is_rejected(string cron)
    {
        var c = SecureJava();
        c.Security.Dast.Schedule.BaselineCron = cron;
        Assert.Contains(PipelineGenerator.Generate(c).Errors, e => e.Path == "security.dast.schedule.baselineCron");
    }

    [Fact]
    public void Injection_through_workflow_fields_is_rejected()
    {
        var c = SecureJava();
        c.Ticketing.ProjectKey = "SEC\" OR 1=1";
        c.Security.Dast.Authenticated.AdminOnlyPaths = ["/admin'; curl evil"];
        c.Security.Dast.Ephemeral.AppEnvironment = ["JAVA_OPTS=-Dx=$(id)"];
        c.RateLimit.Login.UsernameField = "user\nname";
        var errors = PipelineGenerator.Generate(c).Errors.Select(e => e.Path).ToList();
        Assert.Contains("ticketing.projectKey", errors);
        Assert.Contains("security.dast.authenticated.adminOnlyPaths", errors);
        Assert.Contains("security.dast.ephemeral.appEnvironment", errors);
        Assert.Contains("rateLimit.login.usernameField", errors);
    }

    [Fact]
    public void Scans_need_an_environment_url()
    {
        var c = SecureJava();
        c.Environments.Single(e => e.Key == "test").Url = null;
        var errors = PipelineGenerator.Generate(c).Errors.Select(e => e.Path).ToList();
        Assert.Contains("security.dast.authenticated.environment", errors);
        Assert.Contains("rateLimit.environments", errors);
    }

    [Theory]
    [InlineData("develop", "^develop$")]
    [InlineData("release/*", "^release/[^/]*$")]
    [InlineData("hotfix/**", "^hotfix/.*$")]
    public void Branch_globs_become_anchored_regexes(string glob, string regex) =>
        Assert.Equal(regex, WorkflowFilesWriter.GlobToRegex(glob));

    [Fact]
    public void Importer_recognises_workflow_tools()
    {
        const string jf = """
            pipeline {
                agent any
                triggers { cron('H */6 * * *') }
                stages {
                    stage('Build') { steps { sh 'mvn -B enforcer:enforce verify' } }
                    stage('Image') { steps { sh 'snyk container test app:1' ; sh 'cosign sign --key k app@sha256:x' } }
                    stage('Infra') { steps { sh 'snyk iac test' } }
                    stage('Ticket') { steps { jiraNewIssue issue: [:], site: 'jira' } }
                }
            }
            """;
        var r = JenkinsfileImporter.Import(jf);
        Assert.True(r.Config.Signing.Enabled);
        Assert.Equal(ScannerTool.Snyk, r.Config.Security.ContainerScanner);
        Assert.Equal(ScannerTool.Snyk, r.Config.Security.IacScanner);
        Assert.Equal(TicketProvider.Jira, r.Config.Ticketing.Provider);
        Assert.True(r.Config.Security.DependencyPinning);
        Assert.Contains(r.Warnings, w => w.Contains("cron"));
    }
}
